        current_kv = (m.group(1), int(m.group(2)), int(m.group(3)))
    elif current_kind and current_kv:
        current_rows.append(line)

# Save last entry
if current_kind and current_kv and current_rows:
    k = current_kv
    if current_kind == "Test input":
        rows = current_rows[-1]  # Only first line is the test input
    elif isinstance(current_kv, tuple) and len(current_kv) >= 2:
        k = current_kv
        rows = [line.split() for line in current_rows[-k[2]:]]
