with open(session_path) as f:
    content = f.read()

# Extract the message text from each message line
# Messages come in format: "content":[{"type":"text","text":"..."}]
all_grids = {}
current_kv = None
current_rows = []
current_kind = None
last_header = None

# Parse by message blocks
message_pattern = r'"type":"message"[^}]+}'
messages = re.findall(message_pattern, content, re.DOTALL | re.IGNORECASE)

for msg in messages:
    # Check for text content
    text_match = re.search(r'"text":"([^"]*)"', msg)
    if text_match:
        text = text_match.group(1)

        # Check for header patterns (case insensitive)
        header_match = re.search(r'(?:Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):', text, re.IGNORECASE)
        if header_match:
            # Save previous entry if any
            if current_kind and current_kv and current_rows:
                if current_kind == "input":
                    all_grids[current_kv] = {
                        "kind": current_kind,
                        "h": int(current_h),
                        "w": int(current_w),
                        "input": [list(map(int, r.split())) for r in current_rows]
                    }
                elif current_kind == "output":
                    all_grids[current_kv] = {
                        "kind": current_kind,
                        "h": int(current_h),
                        "w": int(current_w),
                        "output": [list(map(int, r.split())) for r in current_rows]
                    }

            current_kind = header_match.group(1).lower()
            current_kv = header_match.group(2)
            current_h = int(header_match.group(3))
            current_rows = []
        elif current_kind:
            # Add line to current rows (skip empty lines)
            if text.strip():
                current_rows.append(text.strip())

# Save last entry
if current_kind and current_kv and current_rows:
    if current_kind == "input":
        all_grids[current_kv] = {
            "kind": current_kind,
            "h": int(current_h),
            "w": int(current_w),
            "input": [list(map(int, r.split())) for r in current_rows]
        }
    elif current_kind == "output":
        all_grids[current_kv] = {
            "kind": current_kind,
            "h": int(current_h),
            "w": int(current_w),
            "output": [list(map(int, r.split())) for r in current_rows]
        }
    elif current_kind == "test":
        # Test input is only the header line's grid embedded in the message
        header_match = re.search(r'Test input \((\d+)x(\d+)\):', text)
        if header_match:
            h, w = int(header_match.group(1)), int(header_match.group(2))
            # The test grid is shown next in the same message, need to extract it
            all_grids[current_kv] = {
                "kind": "test",
                "h": h,
                "w": w,
                "test": [list(map(int, r.split())) for r in current_rows]
            }

print("Found grids:")
for kind, kv in sorted(all_grids.items()):
    print(f"  {kind} {kv['h']}x{kv['w']}: {len('')//0+kv['h']} rows")

# Combine input+output pairs
pairs = []
for kv in all_grids:
    if all_grids[kv].get("input") is not None or all_grids[kv].get("output") is not None:
        pairs.append({
            "key": kv,
            "h": all_grids[kv]["h"],
            "w": all_grids[kv]["w"],
            "input": all_grids[kv].get("input"),
            "output": all_grids[kv].get("output"),
            "kind": all_grids[kv]["kind"]
        })

for p in pairs[:5]:
    print(f"\nPair: {p['key']}")
    if p['input']:
        print("Input:")
        for row in p['input']:
            print("  ", row)
    if p['output']:
