import re, os

d = os.environ.get('RLM_SESSION_DIR')
session_path = os.path.join(d, '../../sessions', os.path.basename(d) + '.jsonl')

with open(session_path) as f:
    content = f.read()

# Search for all Demo patterns directly in content
pattern = r'(?:Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):'

# Find start positions
starts = [m.start() for m in re.finditer(pattern, content, re.IGNORECASE)]
print(f"Found {len(starts)} head patterns at positions: {starts[:10]}...")

# For each start, extract h, w and following lines
all_grids = {}

for start in starts:
    m = re.match(pattern, content[start:start+50])
    if not m:
        continue
    kind = m.group(1).lower()
    k = m.group(2)
    h = int(m.group(3))

    # Find next matching header
    end = content.find(pattern[start+100:] if start+100 < len(content) else "", start+10)
    if end > 0:
        text = content[start:end]
    else:
        text = content[start:].strip()

    # Parse rows until we hit a non-grid line
    rows = []
    for line in text.split('\n')[:h+10]:
        row = [int(x) for x in line.split() if x.strip() != '' and x.strip() != '{']
        if row:
            rows.append(row)

    if not lines:
        continue

    all_grids[k + ('_in' if kind == 'input' else '_out' if kind == 'output' else '_test')] = {
        "size": f"{h}x{w}",
        "kind": kind,
        "rows": rows
    }

for k in sorted(all_grids.keys()):
    print(f"{k}: {all_grids[k]['size']}")

import re, os

d = os.environ.get('RLM_SESSION_DIR')
session_path = os.path.join(d, '../../sessions', os.path.basename(d) + '.jsonl')

with open(session_path) as f:
    content = f.read()

# Simpler approach: find each pattern occurrence
matches = list(re.finditer(r'Demo pair \d+ (?:input|output)|Test input', content))

all_grids = {}

for i, m in enumerate(matches):
    pos = m.start()

    # Get 10 lines after the header
    text = content[pos:pos+2000] if pos+2000 < len(content) else content[pos:]

    # Count (h)x(w) occurrences
    hws = list(re.findall(r'\((\d+)x(\d+)\):', text))

    if hws:
        h, w = hws[0]
        h, w = int(h), int(w)
        kind = m.group(1).lower()

        # Extract grid rows
        rows = []
        parts = text.split('\n')
        for line in parts[:h+50]:
            row = [int(x) for x in line.split() if x.strip() and not x.strip().startswith('http')]
            if row:
                if len(row) <= w and all(x.isdigit() for x in row):
                    rows.append(row)

        key = f"{kind}_{i}"
        all_grids[key] = {"kind": kind, "h": h, "w": w, "rows": rows}

print(len(all_grids), "grids found")
for k in all_grids:
    g = all_grids[k]
    print(f"  {k}: {g['h']}x{g['w']} ({len(g['rows'])} rows)")
    if g['kind'] == 'test':
        print("    Test input grid:")
        for row in g['rows'][:5]:
            print("      ", row)
    elif g['kind'] == 'input':
        print("    Input grid (first 3 rows):")
        for row in g['rows'][:3]:
            print("      ", row)
    elif g['kind'] == 'output':
        print("    Output grid (first 3 rows):")
        for row in g['rows'][:3]:
            print("      ", row)
